const $=id=>document.getElementById(id);
let baseSongs=[], songs=[], stopSongs=null, editingSong=null, songBusy=false, user=null, cloud=null, records=[], unsubscribe=null, expectedUpdatedAt=null, dirty=false, saving=false, fromCache=true, viewMode="moderator", sharing=false, baseline=null, autoRunning=false, autoScheduled=false, autoError='', detailConflicts=[], autoLoadDone=false, choseNew=false, syncMessage='Song changes saved', artistAuto='', heartChanges=new Map(), timer;
const blank=()=>({ids:[],songNotes:{},event:'',notes:'',date:'',startTime:'',endTime:'',cloudId:null,ownerUid:null,ownerEmail:null,access:{},sharedWith:[]});
let plan=blank(), storageOK=true, stopNotes=null, notesPlanId=null, noteSongId=null, noteBusy=false;
function draftKey(){return user?'n64-draft-'+user.uid:'n64-plan-v1';}
function restoreDraft(){plan=blank();baseline=null;try{const p=JSON.parse(localStorage.getItem(draftKey()));if(p&&Array.isArray(p.ids)){plan={...plan,...p,ids:[...new Set(p.ids.filter(id=>Number.isInteger(id)||typeof id==='string'&&/^song_[a-f0-9]{64}$/.test(id)))],event:typeof p.event==='string'?p.event.slice(0,120):'',notes:typeof p.notes==='string'?p.notes.slice(0,4000):''};baseline=p._baseline||null;expectedUpdatedAt=p._stamp||null;delete plan._baseline;delete plan._stamp;}}catch(e){storageOK=false;}dirty=true;}
restoreDraft();
const readOnly=()=>!!plan.ownerUid&&!canEditSetlist(plan,user);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const parseId=s=>/^\d+$/.test(s)?Number(s):s;
const moderator=()=>isBand(user)&&viewMode==='moderator';
const heartCount=s=>heartChanges.get(s.key)?.count??s.likes??0;
const heart=s=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 21s-9-5.5-9-12a5 5 0 0 1 9-3 5 5 0 0 1 9 3c0 6.5-9 12-9 12Z"/></svg><span>${heartCount(s)}</span>`;
const time=s=>s==null?'—':`${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`;
function toast(msg){$('toast').textContent=msg;$('toast').style.display='block';clearTimeout(timer);timer=setTimeout(()=>$('toast').style.display='none',2200);}
function save(){if(!readOnly()){try{localStorage.setItem(draftKey(),JSON.stringify({...plan,_baseline:baseline,_stamp:expectedUpdatedAt}));storageOK=true;}catch(e){storageOK=false;}}$('saveStatus').textContent=storageOK?plan.cloudId?'Song changes sync automatically. Save event details separately.':'Draft kept on this device. Save this setlist once to enable automatic song updates.':'Device saving is unavailable. Save for Nickel 64 or download a copy before closing.';renderCloudState();}
function schedule(){const start=clockMinutes(plan.startTime),end=clockMinutes(plan.endTime),minutes=durationMinutes(start,end);$('eventDuration').textContent=minutes==null?'Add distinct start and end times to calculate event duration.':`Event duration: ${durationLabel(minutes)}${end<start?' · ends the next day':''}`;}
function detailsDirty(){return !baseline||!sameDetails(plan,baseline);}
function songsDirty(){return !!baseline&&!sameIds(plan.ids,baseline.ids);}
function syncDirty(){dirty=!plan.cloudId||detailsDirty()||songsDirty();}
function renderCloudState(){watchCurrentNotes();const ro=readOnly(),syncing=autoRunning||autoScheduled;$('openDatePicker').disabled=ro||saving;
 $('sharePlan').hidden=!plan.cloudId;$('sharePlan').disabled=saving||syncing;$('sharePlan').textContent=canManageSetlist(plan,user)?'Manage sharing':'Sharing';
 ['event','date','startTime','endTime','notes'].forEach(id=>$(id).disabled=ro||saving);
 $('newPlan').disabled=saving||syncing;$('signOut').disabled=saving||syncing;$('viewMode').disabled=saving||syncing;$('clear').disabled=ro||saving||!plan.ids.length;
 $('cloudSave').disabled=saving||ro||syncing||!!autoError||!!detailConflicts.length||(!!plan.cloudId&&!detailsDirty());
 $('cloudSave').textContent=saving?'Saving…':plan.cloudId?'Save event details':'Save for Nickel 64';
 $('cloudSave').title=plan.cloudId?'Song additions, removals and order changes save automatically. Use this button for event name, date, time or notes.':'Save the event details once to enable automatic song updates.';
 $('syncActions').hidden=!autoError&&!detailConflicts.length;$('retrySongs').hidden=!autoError;$('retrySongs').disabled=syncing;
 if(ro)$('cloudStatus').textContent='Viewing this setlist with view-only access.';
 else if(autoError)$('cloudStatus').textContent='Songs are kept on this device but have not synced. '+autoError;
 else if(detailConflicts.length)$('cloudStatus').textContent='Event details changed on another device. Reload the saved version to resolve the competing edits.';
 else if(!cloud)$('cloudStatus').textContent='Connecting to shared setlists…';
 else if(!user)$('cloudStatus').textContent='Sign in to save a setlist for Dave and Rob.';
 else if(!user.emailVerified)$('cloudStatus').textContent='Verify your email, then check verification to save for Dave and Rob.';
 else if(syncing)$('cloudStatus').textContent='Syncing songs for Nickel 64 and shared users…';
 else $('cloudStatus').textContent=plan.cloudId?(detailsDirty()?'Songs sync automatically. Event details have unsaved changes.':'Songs sync automatically for Nickel 64 and shared users.'): 'Save this setlist once; future song changes will sync automatically.';
}

function library(){$('requestSongButton').textContent=isBand(user)?'Add a song':'Request a song';const q=$('search').value.trim().toLowerCase(),d=$('decade').value,sort=$('sort').value;const list=songs.filter(s=>(s.status==='approved'||user?.emailVerified)&&(s.title+' '+s.artist).toLowerCase().includes(q)&&(d==='all'||s.year&&Math.floor(s.year/10)*10===Number(d))).sort((a,b)=>sort==='year'?(b.year||0)-(a.year||0):sort==='bpm'?(a.bpm??Infinity)-(b.bpm??Infinity):String(a[sort]).localeCompare(String(b[sort])));$('count').textContent=`${list.length} songs`;$('songs').innerHTML=list.length?list.map(s=>`<div class="song" data-library-song="${s.id}" tabindex="-1"><div><div class="title song-heading"><span>${esc(s.title)}${s.status!=='approved'?` <span class="request-badge ${s.status}">${s.status==='pending'?'Awaiting review':'Request denied'}</span>`:''}</span>${renderMusicLinks(s,esc)}</div><div class="artist">${esc(s.artist)}</div>${moderator()?`<button class="song-edit" data-edit-song="${esc(s.key)}">Edit details</button>`:''}</div><span class="meta year">${s.year||'—'}</span><span class="meta">${s.bpm||'—'}</span><span class="meta">${time(s.seconds)}</span><button class="heart" data-heart="${esc(s.key)}" aria-label="Support ${esc(s.title)}; ${heartCount(s)} hearts">${heart(s)}</button><button data-add="${s.id}" ${readOnly()||saving?'disabled':''} class="${plan.ids.includes(s.id)?'added':''}" aria-label="${plan.ids.includes(s.id)?'Remove':'Add'} ${esc(s.title)} ${plan.ids.includes(s.id)?'from':'to'} setlist" aria-pressed="${plan.ids.includes(s.id)}">${plan.ids.includes(s.id)?'✓':'+'}</button></div>`).join(''):'<div class="no-results">No songs found. Try another song, artist or decade.</div>';}
function canWriteSongNote(){return !isBand(user)&&!readOnly()&&!saving&&(!plan.cloudId||!!user?.emailVerified);}
function selected(){const list=plan.ids.map(id=>songs.find(s=>s.id===id)).filter(Boolean),secs=list.reduce((sum,s)=>sum+(s.seconds||0),0),missing=list.filter(s=>s.seconds==null).length;$('selectedCount').textContent=list.length;$('minutes').textContent=`${Math.round(secs/60)} min`;$('unknown').textContent=missing?`${missing} song${missing===1?' has':'s have'} no duration; the total excludes ${missing===1?'it':'them'}.`:'';$('empty').hidden=!!list.length;$('setlist').innerHTML=list.map((s,i)=>`<li><span class="number">${String(i+1).padStart(2,'0')}</span><div class="selected-song"><button class="setlist-song-title" data-find-song="${s.id}" title="Find this song in the repertoire">${esc(s.title)}</button><small>${esc(s.artist)} · ${time(s.seconds)}</small>${plan.songNotes?.[s.id]?`<small class="song-note-print">Note: ${esc(plan.songNotes[s.id])}</small>`:''}${s.status!=='approved'?`<span class="request-badge ${s.status}">${s.status==='denied'?'Request denied':'Awaiting review'}</span>`:''}</div><div class="actions"><button class="song-note-button ${plan.songNotes?.[s.id]?'has-note':''}" data-note="${s.id}" title="${esc(plan.songNotes?.[s.id]||'No song note yet')}" aria-label="${canWriteSongNote()?'Edit':'View'} note for ${esc(s.title)}"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m4 16-1 5 5-1L20 8l-4-4Z M14 6l4 4"/></svg></button><button data-move="${s.id}" data-dir="-1" aria-label="Move ${esc(s.title)} up" ${readOnly()||saving||i===0?'disabled':''}>↑</button><button data-move="${s.id}" data-dir="1" aria-label="Move ${esc(s.title)} down" ${readOnly()||saving||i===list.length-1?'disabled':''}>↓</button><button ${readOnly()||saving?'disabled':''} data-remove="${s.id}" aria-label="Remove ${esc(s.title)}">×</button></div></li>`).join('');$('export').disabled=!list.length;$('print').disabled=!list.length;$('clear').disabled=readOnly()||saving||!list.length;}
function update(changed=true){if(changed)dirty=true;else syncDirty();library();selected();schedule();save();renderRequests();}function songChanged(message){syncMessage=message;syncDirty();update(false);if(plan.cloudId&&user?.emailVerified&&!readOnly()){autoError='';autoScheduled=true;renderCloudState();queueMicrotask(syncSongs);}else toast(message+' · kept in this draft.');}
function toggle(id){if(readOnly()||saving)throw new Error('This setlist cannot be edited right now');const song=songs.find(s=>s.id===id);if(!song)throw new Error('Unknown song');const removed=plan.ids.includes(id);if(removed){plan.ids=plan.ids.filter(x=>x!==id);supportSong(song,true,false);}else{plan.ids.push(id);supportSong(song,true,true);}songChanged(removed?'Song removed':'Song added');}

$('songs').addEventListener('click',e=>{const add=e.target.closest('[data-add]'),like=e.target.closest('[data-heart]'),edit=e.target.closest('[data-edit-song]');if(add)toggle(parseId(add.dataset.add));else if(like)supportSong(songs.find(s=>s.key===like.dataset.heart));else if(edit)openSong(songs.find(s=>s.key===edit.dataset.editSong));});$('setlist').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.findSong!==undefined)findLibrarySong(parseId(b.dataset.findSong));else if(b.dataset.note!==undefined)openSongNote(parseId(b.dataset.note));else if(b.dataset.remove!==undefined)toggle(parseId(b.dataset.remove));else if(b.dataset.move!==undefined){const i=plan.ids.indexOf(parseId(b.dataset.move)),j=i+Number(b.dataset.dir);if(!readOnly()&&!saving&&i>=0&&j>=0&&j<plan.ids.length){[plan.ids[i],plan.ids[j]]=[plan.ids[j],plan.ids[i]];songChanged('Song order updated');}}});['search','decade','sort'].forEach(id=>$(id).addEventListener('input',library));['event','notes','date','startTime','endTime'].forEach(id=>$(id).addEventListener('input',()=>{if(readOnly())return;plan[id]=$(id).value;const hadConflict=detailConflicts.length;detailConflicts=detailConflicts.filter(key=>plan[key]!==baseline?.[key]);if(hadConflict&&!detailConflicts.length){const current=records.find(r=>r.id===plan.cloudId);if(current)expectedUpdatedAt=current.updatedAt;}syncDirty();schedule();dateHint();save();}));$('clear').onclick=()=>{if(readOnly()||saving)return;if(confirm('Clear all selected songs? Your event name and notes will stay.')){for(const id of plan.ids)supportSong(songs.find(s=>s.id===id),true,false);plan.ids=[];songChanged('Songs cleared');}};$('print').onclick=()=>window.print();$('export').onclick=()=>{const list=plan.ids.map(id=>songs.find(s=>s.id===id)).filter(Boolean),secs=list.reduce((n,s)=>n+(s.seconds||0),0);const txt=`NICKEL 64 SETLIST\n${plan.event||'Event music plan'}\nDate: ${plan.date||'Not set'}\nTime: ${plan.startTime||'—'}–${plan.endTime||'—'}${clockMinutes(plan.endTime)<clockMinutes(plan.startTime)?' (next day)':''}\nEvent duration: ${durationLabel(durationMinutes(clockMinutes(plan.startTime),clockMinutes(plan.endTime)))}\n\n${list.map((s,i)=>`${i+1}. ${s.title} — ${s.artist} (${time(s.seconds)})${s.status!=='approved'?' ['+s.status+' request]':''}${plan.songNotes?.[s.id]?'\n   Note: '+plan.songNotes[s.id]:''}`).join('\n')}\n\n${list.length} songs · ${Math.round(secs/60)} minutes of known durations\nTimes are estimates; missing durations are excluded.\n\nNOTES\n${plan.notes||'None'}\n\nConfirm songs and arrangements with N64.\n`;const url=URL.createObjectURL(new Blob([txt],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='N64-setlist.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Setlist downloaded. Ready to send to N64.');};
async function init(){try{for(const id of ['startTime','endTime'])$(id).innerHTML='<option value="">Choose time</option>'+Array.from({length:96},(_,i)=>{const hours=Math.floor(i/4),minutes=i%4*15,value=String(hours).padStart(2,'0')+':'+String(minutes).padStart(2,'0');return `<option value="${value}">${hours%12||12}:${String(minutes).padStart(2,'0')} ${hours<12?'AM':'PM'}</option>`;}).join('');const r=await fetch('songs.json');if(!r.ok)throw new Error('Library unavailable');baseSongs=await r.json();songs=await Promise.all(baseSongs.map(async s=>({...s,status:'approved',likes:0,key:await songKey(s.title,s.artist)})));baseSongs=songs;plan.ids=plan.ids.filter(id=>typeof id==='string'||songs.some(s=>s.id===id));$('total').textContent=songs.length;const decades=[...new Set(songs.filter(s=>s.year).map(s=>Math.floor(s.year/10)*10))].sort((a,b)=>b-a);$('decade').innerHTML+=decades.map(d=>`<option value="${d}">${d}s</option>`).join('');fillPlan();update(false);registerTools();connectCloud();}catch(e){$('songs').innerHTML='<p>Unable to load the song library. Please reload the page.</p>';return;}}

function registerTools(){if(!document.modelContext?.registerTool)return;try{Promise.resolve(document.modelContext.registerTool({name:'search_n64_songs',description:'Find songs in the N64 library.',inputSchema:{type:'object',properties:{query:{type:'string'}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(!input||typeof input.query!=='string')throw new Error('query must be text');const q=input.query.toLowerCase();return songs.filter(s=>s.status==='approved'&&(s.title+' '+s.artist).toLowerCase().includes(q));}})).catch(()=>{});Promise.resolve(document.modelContext.registerTool({name:'add_songs_to_setlist',description:'Add library songs to the current device setlist.',inputSchema:{type:'object',properties:{songIds:{type:'array',items:{oneOf:[{type:'integer'},{type:'string',pattern:'^song_[a-f0-9]{64}$'}]}}},required:['songIds'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||!Array.isArray(input.songIds)||input.songIds.some(id=>!songs.some(s=>s.id===id&&s.status==='approved')))throw new Error('Use valid song IDs');if(readOnly()||saving)throw new Error('This setlist cannot be edited right now');for(const id of input.songIds)if(!plan.ids.includes(id)){plan.ids.push(id);supportSong(songs.find(s=>s.id===id),true);}songChanged('Songs added');return {songIds:plan.ids};}})).catch(()=>{});}catch(e){}}


function fillPlan(){for(const id of ['startTime','endTime']){const select=$(id);select.querySelector('[data-legacy]')?.remove();if(plan[id]&&!Array.from(select.options).some(o=>o.value===plan[id])){const option=new Option(plan[id]+' (saved time)',plan[id]);option.dataset.legacy='true';select.add(option);}}['event','notes','date','startTime','endTime'].forEach(id=>$(id).value=plan[id]||'');dateHint();}
function errorMessage(error){const messages={'auth/unauthorized-domain':'Sign-in is not enabled for this website yet. Please contact the app owner.','auth/operation-not-allowed':'This sign-in method is not enabled yet. Try another method.','auth/invalid-credential':'The email or password is incorrect.','auth/email-already-in-use':'This email already has an account. Sign in instead.','auth/weak-password':'Use a password with at least six characters.','auth/popup-blocked':'Allow the sign-in popup and try again.','auth/popup-closed-by-user':'Sign-in was cancelled.','auth/network-request-failed':'Connection failed. Please try again.','permission-denied':'Access was denied. Check your email verification or contact the app owner.','unavailable':'Shared setlists are temporarily unavailable. Your draft has been kept.'};return messages[error.code]||error.message||'Something went wrong. Please try again.';}
function openAuth(){if(!cloud){toast('Shared sign-in is unavailable. Please reload and try again.');return;}$('authStatus').textContent='';$('authDialog').showModal();}
$('signIn').onclick=openAuth;$('closeAuth').onclick=()=>$('authDialog').close();
$('signOut').onclick=async()=>{try{await cloud.logOut();}catch(e){toast(errorMessage(e));}};
async function authAction(action){try{$('authStatus').textContent='Signing in…';await action();$('authPassword').value='';$('authDialog').close();}catch(e){$('authStatus').textContent=errorMessage(e);}}
$('googleSignIn').onclick=()=>authAction(()=>cloud.googleSignIn());
$('authForm').onsubmit=e=>{e.preventDefault();authAction(()=>cloud.emailSignIn($('authEmail').value.trim(),$('authPassword').value));};
$('createAccount').onclick=()=>{if(!$('authForm').reportValidity())return;authAction(async()=>{await cloud.register($('authEmail').value.trim(),$('authPassword').value);toast('Verification email sent. Verify your email to save a setlist.');});};
$('resetPassword').onclick=async()=>{if(!$('authEmail').reportValidity())return;try{await cloud.resetPassword($('authEmail').value.trim());$('authStatus').textContent='If an account exists, a password reset email has been sent.';}catch(e){$('authStatus').textContent=errorMessage(e);}};
$('newPlan').onclick=()=>{if(autoRunning||autoScheduled)return;if(dirty&&(plan.ids.length||plan.event)&&!confirm('Start a new setlist? Download or save the current draft first to keep it.'))return;plan=blank();baseline=null;autoError='';detailConflicts=[];choseNew=true;expectedUpdatedAt=null;fillPlan();update();};
$('cloudSave').onclick=async()=>{
 if(saving||autoRunning||autoScheduled||autoError||detailConflicts.length)return;
 if(!cloud){toast('Shared saving is unavailable. Please reload and try again.');return;}
 if(!user){openAuth();return;}
 if(!user.emailVerified){try{await cloud.verifyEmail();toast('Verification email sent. Open the link, then check verification.');}catch(e){toast(errorMessage(e));}return;}
 if(readOnly())return;
 if(!plan.event.trim()||!validDate(plan.date)||durationMinutes(clockMinutes(plan.startTime),clockMinutes(plan.endTime))==null||(!plan.cloudId&&!plan.ids.length)){$('cloudStatus').textContent='Add an event name, date, distinct start and end times, and at least one song.';return;}
 saving=true;renderCloudState();library();selected();
 try{const submitted=JSON.parse(JSON.stringify(plan)),result=await cloud.savePlan(submitted,expectedUpdatedAt);plan.cloudId=result.id;Object.assign(plan,{ownerUid:result.record.ownerUid,ownerEmail:result.record.ownerEmail,access:result.record.access||{},sharedWith:result.record.sharedWith||[]});expectedUpdatedAt=result.updatedAt;baseline=JSON.parse(JSON.stringify(plan));autoError='';detailConflicts=[];dirty=false;save();toast('Setlist saved for Dave and Rob.');}catch(e){$('cloudStatus').textContent=errorMessage(e);saving=false;library();selected();renderCloudState();$('cloudStatus').textContent=errorMessage(e);$('cloudSave').disabled=readOnly();$('cloudSave').textContent=plan.cloudId?'Save event details':'Save for Nickel 64';return;}
 saving=false;library();selected();renderCloudState();
};
function fromRecord(r){return {...blank(),songNotes:plan.cloudId===r.id?plan.songNotes||{}:{},cloudId:r.id,ownerUid:r.ownerUid,ownerEmail:r.ownerEmail,access:r.access||{},sharedWith:r.sharedWith||[],event:r.event,notes:r.notes,date:r.eventDate.toDate().toISOString().slice(0,10),startTime:formatClock(r.startMinutes),endTime:formatClock(r.endMinutes),ids:[...r.songIds]};}
function formatClock(m){return `${String(Math.floor(m/60)).padStart(2,'0')}:${String(m%60).padStart(2,'0')}`;}
function visibleRecords(){return isBand(user)&&viewMode==='moderator'?records:records.filter(r=>regularVisible(r,user));}
function renderRecords(){
 $('savedTitle').textContent=isBand(user)&&viewMode==='moderator'?'All setlists · Moderator':'Your owned and shared setlists';
 const sorted=[...visibleRecords()].sort((a,b)=>a.eventDate.toMillis()-b.eventDate.toMillis()||a.startMinutes-b.startMinutes);
 $('savedPlans').innerHTML=sorted.map(r=>`<button class="saved-card" data-record="${esc(r.id)}" aria-current="${r.id===plan.cloudId?'true':'false'}"><strong>${esc(r.event)}</strong><span>${r.eventDate.toDate().toISOString().slice(0,10)} · ${formatClock(r.startMinutes)}–${formatClock(r.endMinutes)}${r.endMinutes<r.startMinutes?' (+1 day)':''}</span><span>${durationLabel(r.durationMinutes)} · ${r.songIds.length} songs</span></button>`).join('');
 $('savedStatus').textContent=fromCache?'Connecting… Saved records shown may be from this device’s cache.':sorted.length?'Saved setlists are available to Dave and Rob.':'No saved setlists yet.';
}
function openRecord(r){plan=fromRecord(r);baseline=fromRecord(r);expectedUpdatedAt=r.updatedAt;autoError='';detailConflicts=[];dirty=false;fillPlan();update(false);renderRecords();}
function maybeAutoLoad(){if(fromCache||moderator()||autoLoadDone||choseNew)return;const visible=visibleRecords();if(visible.length!==1)return;const r=visible[0];if((plan.cloudId===r.id&&!dirty)||(!plan.cloudId&&!plan.ids.length&&!plan.event&&!plan.notes&&!plan.date&&!plan.startTime&&!plan.endTime)){autoLoadDone=true;openRecord(r);}}
$('savedPlans').onclick=e=>{const b=e.target.closest('[data-record]');if(!b||saving||autoRunning||autoScheduled)return;if(b.dataset.record===plan.cloudId)return;const r=visibleRecords().find(r=>r.id===b.dataset.record);if(!r)return;if(dirty&&(plan.ids.length||plan.event)&&!confirm('Open the saved setlist? Unsaved changes to the current draft will be replaced.'))return;autoLoadDone=true;openRecord(r);};
function receiveCurrent(current){const remote=fromRecord(current);Object.assign(plan,{ownerUid:current.ownerUid,ownerEmail:current.ownerEmail,access:current.access||{},sharedWith:current.sharedWith||[]});
 if(saving)return;
 if(readOnly()){openRecord(current);return;}
 if(!baseline){if(!dirty||plan.cloudId===current.id){openRecord(current);}return;}
 const pending=songsDirty()||autoRunning||autoScheduled;
 const merged=mergeDetails(plan,baseline,remote);Object.assign(plan,merged.values);detailConflicts=[...new Set([...detailConflicts.filter(key=>plan[key]!==remote[key]),...merged.conflicts])];
 for(const key of DETAIL_FIELDS)baseline[key]=remote[key];
 if(!pending){plan.ids=[...remote.ids];baseline.ids=[...remote.ids];}
 if(!detailConflicts.length)expectedUpdatedAt=current.updatedAt;
 fillPlan();update(false);if(songsDirty()&&!autoRunning&&!autoScheduled&&!autoError){autoScheduled=true;renderCloudState();queueMicrotask(syncSongs);}
}
async function syncSongs(){if(autoRunning)return;autoScheduled=false;if(!plan.cloudId||!baseline||readOnly()||!user?.emailVerified)return;autoRunning=true;const id=plan.cloudId,uid=user.uid;renderCloudState();
 try{while(songsDirty()){const ids=[...plan.ids],expectedIds=[...baseline.ids];const current=await cloud.saveSongs(id,ids,expectedIds);if(plan.cloudId!==id||user?.uid!==uid)return;
 const remote=fromRecord(current),merged=mergeDetails(plan,baseline,remote);Object.assign(plan,merged.values);detailConflicts=[...new Set([...detailConflicts.filter(key=>plan[key]!==remote[key]),...merged.conflicts])];for(const key of DETAIL_FIELDS)baseline[key]=remote[key];baseline.ids=[...ids];if(!detailConflicts.length)expectedUpdatedAt=current.updatedAt;Object.assign(plan,{ownerUid:current.ownerUid,ownerEmail:current.ownerEmail,access:current.access||{},sharedWith:current.sharedWith||[]});fillPlan();syncDirty();save();}
 autoError='';toast(syncMessage+' · saved for Nickel 64 and shared users.');
 }catch(e){autoError=errorMessage(e);toast('Song changes kept locally. Sync needs attention.');}
 finally{autoRunning=false;autoScheduled=false;syncDirty();update(false);}
}
$('retrySongs').onclick=()=>{autoError='';autoScheduled=true;renderCloudState();syncSongs();};
$('reloadPlan').onclick=()=>{if(autoRunning||saving)return;const record=records.find(r=>r.id===plan.cloudId);if(record)openRecord(record);};

async function connectCloud(){try{cloud=await import('./cloud.js');cloud.watchUser(next=>{
 const previous=user;stopNotes?.();stopNotes=null;notesPlanId=null;$('songNoteDialog').close();unsubscribe?.();unsubscribe=null;stopSongs?.();records=[];user=next;
 if(previous?.uid!==next?.uid){autoLoadDone=false;choseNew=false;autoError='';detailConflicts=[];}
 stopSongs=cloud.watchSongs(user,data=>{const map=new Map(baseSongs.map(s=>[s.id,s]));for(const song of data)map.set(song.id,song);songs=[...map.values()];$('total').textContent=songs.filter(s=>s.status==='approved'||user?.emailVerified).length;refreshDecades();library();selected();renderRequests();},error=>{$('requestsStatus').textContent=errorMessage(error);});
 // A guest draft follows the first sign-in. Account-to-account switches use separate device drafts.
 if(previous?.uid!==next?.uid){if(!previous&&next&&!plan.cloudId){const guest=plan;restoreDraft();if(!plan.ids.length&&!plan.event)plan=guest;fillPlan();save();}else{restoreDraft();fillPlan();}}
 $('viewControl').hidden=!isBand(user);$('accountLabel').textContent=user?.email||'';$('signIn').hidden=!!user;$('signOut').hidden=!user;$('savedPanel').hidden=!user;$('savedTitle').textContent=isBand(user)?'All setlists':'Your saved setlists';
 $('verificationActions').hidden=!user||user.emailVerified;
 if(user?.emailVerified){$('savedStatus').textContent='Loading saved setlists…';unsubscribe=cloud.watchPlans(user,(data,cached)=>{records=data;fromCache=cached;renderRecords();const current=data.find(r=>r.id===plan.cloudId);if(current&&!cached){receiveCurrent(current);if($('shareDialog').open)renderSharing();}else if(!cached&&plan.cloudId&&!saving&&!autoRunning){plan=blank();baseline=null;expectedUpdatedAt=null;dirty=false;fillPlan();update(false);$('shareDialog').close();}maybeAutoLoad();},error=>{$('savedStatus').textContent=errorMessage(error);});}
 else{$('savedPlans').innerHTML='';$('savedStatus').textContent=user?'Verify your email to view and save shared setlists.':'';}
 update(false);renderRequests();
 });}catch(e){$('cloudStatus').textContent='Shared saving is unavailable. You can still browse songs and download your draft.';cloud=null;$('signIn').disabled=true;}}
$('checkVerification').onclick=async()=>{try{const refreshed=await cloud.refreshUser();if(refreshed?.emailVerified){location.reload();}else toast('Email is not verified yet. Open the verification email first.');}catch(e){toast(errorMessage(e));}};
init();

$('viewMode').onchange=()=>{viewMode=$('viewMode').value;if(plan.cloudId&&!visibleRecords().some(r=>r.id===plan.cloudId)){plan=blank();baseline=null;expectedUpdatedAt=null;dirty=false;fillPlan();update(false);}renderRecords();maybeAutoLoad();library();renderRequests();toast(viewMode==='moderator'?'Moderator view: all setlists, as Rob and Dave see them.':'Regular user view: your owned and shared setlists.');};
function renderSharing(){const manage=canManageSetlist(plan,user);$('shareForm').hidden=!manage;$('shareList').innerHTML=`<div class="share-person"><span class="person-email">${esc(plan.ownerEmail||'Original creator')}</span><span>Original owner</span></div>`+Object.entries(plan.access||{}).map(([email,role])=>`<div class="share-person"><span class="person-email">${esc(email)}</span>${manage?`<select data-share-email="${esc(email)}" aria-label="Access for ${esc(email)}" ${sharing?'disabled':''}>${[['editor','Can edit'],['viewer','View only'],['owner','Additional owner']].map(([value,label])=>`<option value="${value}" ${role===value?'selected':''}>${label}</option>`).join('')}</select><button data-unshare="${esc(email)}" ${sharing?'disabled':''}>Remove</button>`:`<span>${esc({editor:'Can edit',viewer:'View only',owner:'Additional owner'}[role])}</span>`}</div>`).join('');$('addShare').disabled=sharing;}
$('sharePlan').onclick=()=>{if(dirty){toast('Save your changes before managing sharing.');return;}$('shareStatus').textContent='';renderSharing();$('shareDialog').showModal();};
$('closeShare').onclick=()=>$('shareDialog').close();
async function applyShare(email,role){if(sharing)return;sharing=true;renderSharing();$('shareStatus').textContent='Updating access…';try{const r=await cloud.changeSharing(plan.cloudId,email,role,expectedUpdatedAt);if(r.accessLost){plan=blank();baseline=null;expectedUpdatedAt=null;dirty=false;fillPlan();update(false);$('shareDialog').close();toast('Your access was removed.');return;}Object.assign(plan,{ownerEmail:r.ownerEmail,access:r.access,sharedWith:r.sharedWith});expectedUpdatedAt=r.updatedAt;save();$('shareStatus').textContent='Sharing updated.';$('shareEmail').value='';$('shareRole').value='editor';}catch(e){$('shareStatus').textContent=errorMessage(e);}finally{sharing=false;renderSharing();renderCloudState();}}
$('shareForm').onsubmit=e=>{e.preventDefault();if($('shareForm').reportValidity())applyShare($('shareEmail').value,$('shareRole').value);};
$('shareList').onchange=e=>{if(e.target.dataset.shareEmail)applyShare(e.target.dataset.shareEmail,e.target.value);};
$('shareList').onclick=e=>{const b=e.target.closest('[data-unshare]');if(b)applyShare(b.dataset.unshare,null);};

function refreshDecades(){const value=$('decade').value,decades=[...new Set(songs.filter(s=>(s.status==='approved'||user?.emailVerified)&&s.year).map(s=>Math.floor(s.year/10)*10))].sort((a,b)=>b-a);$('decade').innerHTML='<option value="all">Every decade</option>'+decades.map(d=>`<option value="${d}">${d}s</option>`).join('');$('decade').value=decades.includes(Number(value))?value:'all';}
async function supportSong(song,silent=false,desired=true){
 if(!song)return;if(!user?.emailVerified){if(!silent)toast('Sign in with a verified email to count your heart.');return;}
 let change=heartChanges.get(song.key);if(!change){change={count:heartCount(song),revision:0,running:false};heartChanges.set(song.key,change);}
 change.count=Math.max(0,change.count+(desired?1:-1));change.desired=desired;change.revision++;library();renderRequests();if(change.running)return;change.running=true;
 try{while(true){const revision=change.revision,result=await cloud.setSongLike(song.key,change.desired);if(revision!==change.revision)continue;for(const s of songs)if(s.key===song.key)s.likes=result.likes;heartChanges.delete(song.key);break;}if(!silent)toast('Your heart is counted.');}
 catch(e){heartChanges.delete(song.key);toast('Heart update could not be saved. '+errorMessage(e));}
 finally{library();renderRequests();}
}

function addRequested(song){if(readOnly()||saving){toast('Open an editable setlist to add this song.');return;}if(!songs.some(s=>s.id===song.id))songs.push(song);if(!plan.ids.includes(song.id)){plan.ids.push(song.id);supportSong(song,true);songChanged('Requested song added');}else toast('This song is already in your setlist.');}

function renderRequests(){const canView=!!user?.emailVerified,q=$('requestSearch').value,status=$('requestStatus').value;const list=canView?matchingSongs(songs,q||' ').filter(s=>s.requestedBy&&s.requestedBy!=='catalog'&&(status==='all'||s.status===status)):[];const all=canView?songs.filter(s=>s.requestedBy&&s.requestedBy!=='catalog'&&(status==='all'||s.status===status)):[];const visible=(q.trim()?list:all).sort((a,b)=>$('requestSort').value==='likes'?(b.likes||0)-(a.likes||0)||a.title.localeCompare(b.title):a.title.localeCompare(b.title));$('requestsStatus').textContent=!canView?'Sign in with a verified email to view and support song requests.':visible.length?`${visible.length} requests · Hearts help Dave and Rob see what people want.`:'No matching requests. Request a song above.';$('songRequests').innerHTML=visible.map(s=>`<article class="request-card"><div class="request-top"><div><strong>${esc(s.title)}</strong><div class="artist">${esc(s.artist)}</div><span class="request-badge ${s.status}">${{pending:'Awaiting review',denied:'Previously denied',approved:'Approved'}[s.status]}</span></div><button class="heart" data-heart="${esc(s.key)}" aria-label="Support ${esc(s.title)}; ${heartCount(s)} hearts">${heart(s)}</button></div><div class="request-actions"><button data-request-add="${esc(s.key)}" ${readOnly()||saving?'disabled':''}>${plan.ids.includes(s.id)?'In your setlist':'Add to setlist'}</button>${moderator()?`<button data-decision="approved" data-song="${esc(s.key)}">Approve</button><button data-decision="denied" data-song="${esc(s.key)}">Deny</button><button data-edit-song="${esc(s.key)}">Edit details</button>`:''}</div></article>`).join('');}
['requestSearch','requestStatus','requestSort'].forEach(id=>$(id).addEventListener('input',renderRequests));
$('songRequests').onclick=async e=>{const b=e.target.closest('button');if(!b)return;const key=b.dataset.heart||b.dataset.requestAdd||b.dataset.editSong||b.dataset.song,song=songs.find(s=>s.key===key);if(!song)return;if(b.dataset.heart)supportSong(song);else if(b.dataset.requestAdd)addRequested(song);else if(b.dataset.editSong)openSong(song);else if(b.dataset.decision){b.disabled=true;try{await cloud.updateSong(song.key,null,b.dataset.decision);toast(b.dataset.decision==='approved'?'Song approved for everyone.':'Request denied; people can still support it.');}catch(e){toast(errorMessage(e));}finally{b.disabled=false;}}};
function showMatches(){if(editingSong)return;const matches=matchingSongs(songs,$('songTitle').value);const artists=[...new Set((matches.length?matches:songs).map(s=>s.artist))].sort();$('artistSuggestions').innerHTML=artists.map(artist=>`<option value="${esc(artist)}"></option>`).join('');if(!$('songArtist').value||$('songArtist').value===artistAuto){const exact=matches.filter(s=>s.title.trim().toLowerCase()===$('songTitle').value.trim().toLowerCase());const candidates=[...new Set((exact.length?exact:matches).map(s=>s.artist))];artistAuto=candidates.length===1?candidates[0]:'';$('songArtist').value=artistAuto;}$('songMatches').innerHTML=matches.length?'Matching titles — choose an existing song or enter another artist:<br>'+matches.slice(0,15).map(s=>`<button type="button" data-match="${esc(s.key)}">${esc(s.title)} · ${esc(s.artist)} (${esc(s.status)})</button>`).join(''):'';}
['songTitle','songArtist'].forEach(id=>$(id).addEventListener('input',showMatches));$('songMatches').onclick=async e=>{const b=e.target.closest('[data-match]');if(b){const song=songs.find(s=>s.key===b.dataset.match);try{if(isBand(user)&&song.status!=='approved'){await cloud.updateSong(song.key,null,'approved');song.status='approved';}if(isBand(user)&&readOnly())toast('Approved song is available in the shared repertoire.');else addRequested(song);$('songDialog').close();}catch(error){$('songFormStatus').textContent=errorMessage(error);}}};
function openSong(song=null){if(!user){openAuth();return;}if(!user.emailVerified){toast('Verify your email to request songs.');return;}if(song&&!moderator())return;if(!song&&!isBand(user)&&(readOnly()||saving)){toast('Open an editable setlist to request a song.');return;}editingSong=song;artistAuto='';$('songForm').reset();$('songMatches').textContent='';$('songFormStatus').textContent='';$('songDialogTitle').textContent=song?'Edit song details':isBand(user)?'Add a song':'Request a song';$('submitSong').textContent=song?'Save for everyone':isBand(user)?'Add approved song':'Request and add to setlist';$('songTitle').value=song?.title||'';$('songArtist').value=song?.artist||'';$('songTitle').disabled=!!song;$('songArtist').disabled=!!song;$('artistSuggestions').innerHTML=[...new Set(songs.map(s=>s.artist))].sort().map(artist=>`<option value="${esc(artist)}"></option>`).join('');for(const key of Object.keys(MUSIC_PLATFORMS))$('link-'+key).value=song?.links?.[key]||'';$('link-n64').closest('label').hidden=!isBand(user);$('songBpm').value=song?.bpm??'';$('songYear').value=song?.year??'';$('songSeconds').value=song?.seconds??'';$('songDecisionLabel').hidden=!song||song.requestedBy==='catalog';$('songDecision').value=song?.status||'pending';$('songDialog').showModal();}
$('requestSongButton').onclick=()=>openSong();$('closeSong').onclick=()=>$('songDialog').close();
$('songForm').onsubmit=async e=>{e.preventDefault();if(songBusy)return;songBusy=true;$('submitSong').disabled=true;$('songFormStatus').textContent='Saving…';try{const details=songDetails({bpm:$('songBpm').value,year:$('songYear').value,seconds:$('songSeconds').value,links:Object.fromEntries(Object.keys(MUSIC_PLATFORMS).filter(key=>key!=='n64'||isBand(user)).map(key=>[key,$('link-'+key).value]))});if(editingSong){await cloud.updateSong(editingSong.key,details,editingSong.requestedBy==='catalog'?'approved':$('songDecision').value);toast('Song updated for everyone.');}else{const title=$('songTitle').value,artist=$('songArtist').value,existing=exactSong(songs,title,artist);if(existing&&Object.keys(details.links).length){if(isBand(user)){await cloud.updateSong(existing.key,{bpm:details.bpm??existing.bpm,year:details.year??existing.year,seconds:details.seconds??existing.seconds,links:{...(existing.links||{}),...details.links}},'approved');existing.links={...(existing.links||{}),...details.links};}else throw new Error('This song already exists. Only moderators can change its recording links. Choose the existing song, or request a different artist.');}const song=existing||await cloud.requestSong({title,artist,...details});if(isBand(user)&&song.status!=='approved'){await cloud.updateSong(song.key,null,'approved');song.status='approved';}if(isBand(user)&&readOnly()){toast('Approved song added to the shared repertoire.');}else addRequested(song);}$('songDialog').close();}catch(e){$('songFormStatus').textContent=errorMessage(e);}finally{songBusy=false;$('submitSong').disabled=false;}};

function dateHint(){const value=$('date').value;$('dateHint').textContent=validDate(value)?new Intl.DateTimeFormat('en-CA',{weekday:'long',year:'numeric',month:'long',day:'numeric',timeZone:'UTC'}).format(new Date(value+'T00:00:00Z')):'Choose your event date.';}
$('openDatePicker').onclick=()=>{if($('date').disabled)return;try{$('date').showPicker?.();}catch{$('date').focus();}};

function watchCurrentNotes(){const id=plan.cloudId;if(id===notesPlanId)return;$('songNoteDialog').close();stopNotes?.();stopNotes=null;notesPlanId=id;if(!id||!cloud||!user?.emailVerified)return;stopNotes=cloud.watchSongNotes(id,notes=>{if(plan.cloudId!==id)return;plan.songNotes=notes;selected();if($('songNoteDialog').open&&!canWriteSongNote())$('songNoteText').value=notes[noteSongId]||'';},error=>toast('Unable to load song notes: '+errorMessage(error)));}
function openSongNote(id){if(noteBusy)return;const song=songs.find(s=>s.id===id);if(!song||!plan.ids.includes(id))return;noteSongId=id;const edit=canWriteSongNote();$('songNoteTitle').textContent=(edit?'Note for ':'View note for ')+song.title;$('songNoteText').value=plan.songNotes?.[id]||'';$('songNoteText').readOnly=!edit;$('saveSongNote').hidden=!edit;$('songNoteShortcuts').hidden=!edit;$('songNoteStatus').textContent=edit?'Saved with this song in this setlist.':'Song notes are provided by the setlist owners and editors.';$('songNoteDialog').showModal();}
$('closeSongNote').onclick=()=>{if(!noteBusy)$('songNoteDialog').close();};
$('songNoteForm').onsubmit=async e=>{e.preventDefault();if(noteBusy||!canWriteSongNote()||!plan.ids.includes(noteSongId))return;const id=plan.cloudId,songId=noteSongId,text=$('songNoteText').value.trim();noteBusy=true;$('saveSongNote').disabled=true;$('songNoteStatus').textContent='Saving…';try{if(id)await cloud.saveSongNote(id,songId,text);if(plan.cloudId===id){plan.songNotes||={};if(text)plan.songNotes[songId]=text;else delete plan.songNotes[songId];save();selected();}$('songNoteDialog').close();toast(text?'Song note saved.':'Song note cleared.');}catch(error){$('songNoteStatus').textContent=errorMessage(error);}finally{noteBusy=false;$('saveSongNote').disabled=false;}};

function findLibrarySong(id){const song=songs.find(s=>s.id===id);if(!song)return;const search=$('search').value.trim();if(search){if(!confirm('Clear the song search and scroll to '+song.title+' in the repertoire?'))return;$('search').value='';}const decade=$('decade').value;if(decade!=='all'&&(!song.year||Math.floor(song.year/10)*10!==Number(decade))){if(!confirm('Clear the decade filter and scroll to '+song.title+' in the repertoire?'))return;$('decade').value='all';}library();const row=Array.from($('songs').children).find(el=>el.dataset.librarySong===String(id));if(!row){toast('This song is not available in the repertoire.');return;}row.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});row.focus({preventScroll:true});row.classList.add('song-highlight');setTimeout(()=>row.classList.remove('song-highlight'),1800);}
$('songNoteShortcuts').onclick=e=>{const button=e.target.closest('[data-note-label]');if(!button||!canWriteSongNote()||noteBusy)return;const input=$('songNoteText'),label=button.dataset.noteLabel,current=input.value.trim();if(!current.split('\n').includes(label)){const value=current?current+'\n'+label:label;if(value.length>input.maxLength){$('songNoteStatus').textContent='The note is full. Shorten it before adding a label.';return;}input.value=value;}input.focus();};
